<?php require __DIR__.'/app/bootstrap.php';$p=query('SELECT * FROM products WHERE slug=? AND active=1',[(string)($_GET['slug']??'')])->fetch();if(!$p){http_response_code(404);render_header('Product not found');echo '<main class="page"><h1>Product not found.</h1><a href="'.url().'">Back to the shop</a></main>';render_footer();exit;}$variants=query('SELECT * FROM variants WHERE product_id=? ORDER BY id',[$p['id']])->fetchAll();$available=array_filter($variants,fn($v)=>$v['stock']===null||(int)$v['stock']>0);$gallery=product_gallery($p);render_header($p['name']); ?>
<main class="page"><a class="back-link" href="<?=url('index.php#shop')?>">← ALL CLOTHING</a><div class="product"><div class="gallery"><div class="product-image"><span class="image-label">FLAWED URBANWEAR</span><img id="main-image" src="<?=url(h(product_photo($p['image'],1280)))?>" alt="<?=h($p['name'])?> — view 1"></div><?php if(count($gallery)>1):?><div class="views gallery-views"><?php foreach($gallery as $i=>$photo):?><button type="button" class="<?=$i===0?'active':''?>" data-image="<?=url(h(product_photo($photo,1280)))?>" aria-pressed="<?=$i===0?'true':'false'?>" data-alt="<?=h($p['name'])?> — view <?=$i+1?>"><img src="<?=url(h(product_photo($photo,240)))?>" alt="View <?=$i+1?>" loading="lazy"></button><?php endforeach ?></div><?php endif ?></div>
<div class="product-details"><p class="eyebrow">FLAWED URBANWEAR / <?=h($p['category']??'CLOTHING')?></p><h1 class="product-title"><?=h($p['name'])?></h1><p class="price"><?=money($p['price'])?> <span>BDT</span></p><?php if(!empty($p['short_description'])):?><p><?=h($p['short_description'])?></p><?php endif ?><p class="stock-status"><?=$available?'AVAILABLE TO ORDER':'SOLD OUT — CURRENTLY UNAVAILABLE'?></p><p class="description"><?=nl2br(h($p['description']))?></p>
<details class="size-guide"><summary>SIZE GUIDE &amp; FIT <span>+</span></summary><?php $guide=setting('size_guide_'.$p['id']);if($guide):?><p><?=nl2br(h($guide))?></p><?php else:?><p>Measurements for this piece are not published yet. <a href="https://www.instagram.com/flawedurbanwear/" target="_blank" rel="noopener">Ask us for measurements</a> before choosing your size.</p><?php endif ?></details>
<details><summary>DELIVERY FEES &amp; ESTIMATES <span>+</span></summary><?php foreach(['dhaka'=>'Inside Dhaka','outside'=>'Outside Dhaka'] as $area=>$label):$fee=setting('delivery_'.$area);$estimate=setting('delivery_estimate_'.$area);?><p><strong><?=$label?></strong>: <?=$fee===null||$fee===''?'Delivery fee confirmed by the team':money($fee)?>.<br><?=h($estimate?:'Delivery timing will be confirmed with your order.')?></p><?php endforeach ?></details>
<form method="post" data-add-to-bag action="<?=url('cart.php')?>"><?=csrf_input()?><input type="hidden" name="product_id" value="<?=h($p['id'])?>"><input type="hidden" name="action" value="add"><fieldset><legend>SELECT SIZE</legend><div class="size-options"><?php foreach($variants as $v):?><label class="size-choice"><input type="radio" name="size" value="<?=h($v['size'])?>" required <?= $v['stock']!==null && (int)$v['stock']===0?'disabled':'' ?>><span><?=h($v['size'])?><small><?=$v['stock']===null?'Available':((int)$v['stock']===0?'Sold out':h($v['stock']).' left')?></small></span></label><?php endforeach ?></div></fieldset><?php if($available):?><label class="quantity-label">QUANTITY<input type="number" min="1" max="20" name="quantity" value="1" required></label><button class="button dark" name="destination" value="cart">ADD TO BAG <span>↗</span></button><button class="button outline" name="destination" value="checkout">BUY NOW ↗</button><?php else:?><button class="button dark" type="button" disabled>SOLD OUT</button><?php endif ?></form>
<p class="order-note">Need help with fit? <a href="https://www.instagram.com/flawedurbanwear/" target="_blank" rel="noopener">Ask us on Instagram ↗</a></p><details open><summary>ORDERING & DELIVERY <span>+</span></summary><p>Order online and provide your delivery details at checkout. Your order starts as pending until the team confirms it. Delivery charges are shown at checkout when configured.</p></details><details><summary>PAYMENTS <span>+</span></summary><p>Cash on delivery is available for order requests. bKash online payment is coming later; this site does not collect your bKash PIN or OTP.</p></details></div></div><?php $related=query('SELECT id,name,slug,image,price FROM products WHERE active=1 AND category=? AND id<>? ORDER BY created_at DESC,id DESC LIMIT 3',[$p['category'],$p['id']])->fetchAll();if($related):?><section class="related-products"><h2>More from <?=h($p['category'])?></h2><div class="related-grid"><?php foreach($related as $item):?><a href="<?=url('product.php?slug='.rawurlencode($item['slug']))?>"><img src="<?=url(h(product_photo($item['image'],640)))?>" loading="lazy" alt="<?=h($item['name'])?>"><h3><?=h($item['name'])?></h3><p><?=money($item['price'])?></p></a><?php endforeach ?></div></section><?php endif ?></main><?php render_footer(); ?>
